# Check left and right ends of cabinet base in obs_0033
from PIL import Image
import numpy as np

img = np.array(Image.open('/work/observations/obs_0033.png'))

# Left end (front-left corner):
for c in range(135, 148):
    for r in range(390, 365, -1):
        if img[r, c, 0] > 200:
            print(f'Left end c={c}: r={r}')
            break

# Right end (back-right corner):
for c in range(230, 245):
    for r in range(410, 385, -1):
        if img[r, c, 0] > 200:
            print(f'Right end c={c}: r={r}')
            break
